$faqs=[
["category"=>"Basics","question"=>"What is customer experience outsourcing?","answer"=>"Customer experience outsourcing is the use of an external specialist to manage selected customer interactions and CX operations. It can include service, technical support, onboarding, retention, customer success, feedback, and related back-office work.","links"=>[["/solutions/customer-experience-solutions","Explore CX solutions"]]],
["category"=>"Basics","question"=>"What is the difference between customer service and customer experience?","answer"=>"Customer service focuses on helping customers with specific questions or problems. Customer experience covers the broader relationship across discovery, purchase, onboarding, use, support, renewal, and advocacy.","links"=>[["/insights/what-is-customer-experience-cx","Read: What Is Customer Experience?"]]],
["category"=>"Basics","question"=>"Is CX outsourcing the same as call center outsourcing?","answer"=>"No. Call center outsourcing traditionally focuses on voice interactions. CX outsourcing can include phone, email, chat, messaging, social channels, customer success, quality assurance, analytics, and supporting workflows across the customer journey.","links"=>[]],
["category"=>"Services","question"=>"Which customer experience services can be outsourced?","answer"=>"Common services include customer care, technical support, order support, onboarding, appointment scheduling, retention, loyalty support, complaint handling, customer success, surveys, and quality monitoring.","links"=>[["/solutions/customer-experience-solutions","View CX services"]]],
["category"=>"Channels","question"=>"Which communication channels can an outsourced CX team manage?","answer"=>"An outsourced CX team can manage phone, email, live chat, SMS, social messaging, web forms, in-app support, and approved community channels. The channel mix should reflect customer preferences and service complexity.","links"=>[]],
["category"=>"Channels","question"=>"What does omnichannel customer support mean?","answer"=>"Omnichannel support connects customer context across channels so the customer does not have to restart the conversation each time. It requires integrated systems, consistent processes, and access to relevant interaction history.","links"=>[]],
["category"=>"Teams","question"=>"Should a CX outsourcing team be dedicated or shared?","answer"=>"Dedicated teams usually fit consistent volume, complex products, and strong brand requirements. Shared teams can fit lower volume, overflow, simple interactions, or seasonal coverage. A hybrid model can combine both.","links"=>[["/insights/dedicated-vs-shared-bpo-teams","Compare team models"]]],
["category"=>"Teams","question"=>"How are outsourced CX agents trained on a brand?","answer"=>"Training should cover products, customer journeys, systems, tone of voice, policies, security, escalation paths, quality standards, and realistic interaction practice. Training continues through coaching and knowledge updates.","links"=>[]],
["category"=>"Teams","question"=>"Can outsourced agents sound like part of the internal team?","answer"=>"Yes, when hiring profiles, training, knowledge, communication style, quality calibration, and coaching are aligned with the brand. Dedicated teams generally develop deeper brand familiarity over time.","links"=>[]],
["category"=>"Metrics","question"=>"Which KPIs measure outsourced customer experience?","answer"=>"Common CX measures include customer satisfaction, first-contact resolution, response time, service level, customer effort, quality score, resolution time, escalation rate, retention, and net promoter score where appropriate.","links"=>[["/solutions/quality-assurance-outsourcing","Explore CX quality assurance"]]],
["category"=>"Metrics","question"=>"What is customer satisfaction score (CSAT)?","answer"=>"CSAT measures how satisfied customers are with a specific interaction, product, or experience. It is commonly collected through a short post-interaction survey and should be reviewed alongside operational and quality data.","links"=>[]],
["category"=>"Metrics","question"=>"What is first-contact resolution?","answer"=>"First-contact resolution measures whether a customer issue is resolved during the first interaction without an avoidable follow-up or transfer. The exact definition should be documented for each operation.","links"=>[]],
["category"=>"Quality","question"=>"How is quality maintained in CX outsourcing?","answer"=>"Quality is maintained through documented standards, interaction monitoring, scorecards, calibration, coaching, knowledge management, customer feedback, root-cause analysis, and action tracking.","links"=>[["/solutions/quality-assurance-outsourcing","View QA outsourcing services"]]],
["category"=>"Quality","question"=>"What is quality calibration in customer support?","answer"=>"Quality calibration is a structured review in which client and provider stakeholders score the same interactions and align on how standards should be interpreted. It improves consistency and coaching accuracy.","links"=>[]],
["category"=>"Implementation","question"=>"How long does it take to launch an outsourced CX team?","answer"=>"Launch time depends on hiring, training, channel setup, integrations, process complexity, security, and team size. EmpireOneCX can launch some standard programs in as little as 72 hours, while complex programs require more preparation.","links"=>[["/contact","Discuss a CX launch"]]],
["category"=>"Implementation","question"=>"What should be included in a CX outsourcing transition plan?","answer"=>"A transition plan should cover scope, volumes, staffing, knowledge transfer, systems, access, training, testing, service levels, quality, reporting, escalation, launch support, and stabilization.","links"=>[]],
["category"=>"Technology","question"=>"Can an outsourced CX team use our CRM and help desk?","answer"=>"Yes. Outsourced teams commonly work in client-approved CRM, ticketing, telephony, knowledge, workforce, and analytics systems using role-based access and documented controls.","links"=>[["/compliance-security/","Review security controls"]]],
["category"=>"Technology","question"=>"How is AI used in outsourced customer experience?","answer"=>"AI can assist with routing, summaries, knowledge retrieval, suggested responses, quality monitoring, forecasting, and self-service. Human agents remain important for judgment, empathy, exceptions, and sensitive conversations.","links"=>[["/insights/ai-in-customer-experience-automation","Read the AI and CX guide"]]],
["category"=>"Security","question"=>"How is customer data protected in CX outsourcing?","answer"=>"Controls should include role-based access, encryption, secure connectivity, workforce training, monitoring, incident response, contractual safeguards, and requirements matched to the data and industry.","links"=>[["/compliance-security/","View compliance and security"]]],
["category"=>"Selection","question"=>"How should a company choose a CX outsourcing provider?","answer"=>"Evaluate relevant experience, channel capability, leadership, hiring, training, quality management, reporting, technology compatibility, security, continuity planning, cultural alignment, and scalability.","links"=>[["/about-us","Learn about EmpireOneCX"],["/case-study","View case studies"]]],
["category"=>"Selection","question"=>"Should a company begin CX outsourcing with a pilot?","answer"=>"A pilot can validate training, workflows, customer outcomes, reporting, and the working relationship before a broader rollout. It should have clear measures and represent normal operating conditions.","links"=>[["/contact","Plan a CX pilot"]]]
